48	const PROCESSING_FEE = 5;
49	const FIRST_INSURANCE_SURCHARGE = 0.1;
50	
51	const BASE_PREMIUMS: Record<string, number> = {
52	  sword: 100,
53	  amulet: 60,
54	  staff: 80,
55	  potion: 40,
56	  rune: 25,
57	};
58	
59	/** Premiums are rounded up — in MHPCO's favour. */
60	const roundPremium = (amount: number): number => Math.ceil(amount);
61	
62	const COMPONENT_BLOCK_SIZE = 3;
63	const COMPONENT_BLOCK_PREMIUM = 60;
64	
65	const quotePremium = (items: Item[]): number => {
66	  const runeCount = items.filter((item) => item.type === "rune").length;
67	  const policyBasePremium =
68	    runeCount === COMPONENT_BLOCK_SIZE
69	      ? COMPONENT_BLOCK_PREMIUM
70	      : items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
71	  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_SURCHARGE;
72	  return roundPremium(
73	    policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE,
74	  );
75	};
76	
77	const runStep = (step: Step): StepResult => {
78	  if (step.op === "quote") {
79	    return { premium: quotePremium(step.items) };
80	  }
81	  throw new Error(`Unsupported step: ${step.op}`);
82	};
83	
84	export const runScenario = (scenario: Scenario): ScenarioResult => ({
85	  results: scenario.steps.map(runStep),
86	});
